def transform(grid):
    objects = []
    for color in range(1, 10):
        cells = [(r, c) for r, row in enumerate(grid) for c, x in enumerate(row) if x == color]
        if not cells:
            continue
        r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
        shape = [row[c0:c0 + 4] for row in grid[r0:r0 + 4]]
        objects.append((r0, c0, any(x == 0 for row in shape for x in row), shape))
    objects.sort(key=lambda item: (item[0], item[1]))
    hollow = [shape for r, c, empty, shape in objects if empty]
    solid = [shape for r, c, empty, shape in objects if not empty]
    rows = max(len(hollow), len(solid))
    output = [[0] * 8 for _ in range(4 * rows)]
    for column, group in enumerate((hollow, solid)):
        for i, shape in enumerate(group):
            for r, row in enumerate(shape):
                for c, value in enumerate(row):
                    output[4 * i + r][4 * column + c] = value
    return output
